"use client";
import Link from "next/link";
import { Crown, Info } from "lucide-react";
import { Tooltip } from "@/components/ui/Tooltip";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { AllowancePill } from "./AllowancePill";
import { StatusLegend } from "./StatusLegend";
import styles from "./history.module.css";
export function PremiumTooltip({
  details = false,
  actionDescription,
}: {
  details?: boolean;
  actionDescription?: string;
}) {
  return (
    <div className="space-y-2">
      {actionDescription && <p>{actionDescription}</p>}
      <p>
        <strong>Premium required</strong>
      </p>
      {details && (
        <p className="text-body">
          Add to shortlist from History, follow-up reminders, and manual reply
          editing.
        </p>
      )}
      <p>
        <Link
          href="/usage"
          className="relative isolate inline-block overflow-hidden align-middle"
        >
          View Premium plan
        </Link>
        {details && (
          <span className="text-body">
            {" "}
            · Checkout is in Usage when configured.
          </span>
        )}
      </p>
    </div>
  );
}
export function HistoryInfoRow() {
  const access = useWorkspaceEntitlements();
  const locked =
    !access.features.historyShortlist ||
    !access.features.followUpReminders ||
    !access.features.markReplied;
  return (
    <div className="flex items-center flex-wrap gap-3 [margin:22px_0_16px]">
      <AllowancePill />
      <div className="ml-auto [@media(max-width:_859px)]:ml-0">
        <Tooltip className="history-surface" content={<StatusLegend />}>
          <button
            type="button"
            className={`${styles.pill} inline-flex items-center flex-wrap gap-2 py-[7px] px-3.5 [border:1px_solid_var(--h-border)] rounded-full [background:var(--h-surface)] text-[13px] text-[var(--h-muted)]`}
          >
            <Info size={16} aria-hidden="true" />
            How statuses work
          </button>
        </Tooltip>
      </div>
      {locked && (
        <Tooltip
          className="history-surface"
          interactive
          content={<PremiumTooltip details />}
        >
          <button
            type="button"
            className={`${styles.pill} inline-flex items-center flex-wrap gap-2 py-[7px] px-3.5 [border:1px_solid_var(--premium-notice-border)] rounded-full [background:var(--premium-notice-background)] text-[13px] text-[var(--premium-notice-text)] font-semibold`}
          >
            <Crown size={16} className="premium-icon" aria-hidden="true" />
            Premium actions
          </button>
        </Tooltip>
      )}
    </div>
  );
}
